function writeMany(stream, chunks) {
  for (const chunk of chunks) {
    const canContinue = stream.write(chunk);

    if (!canContinue) {
      stream.once('drain', () => {
        writeMany(stream, chunks.slice(1));
      });
      return;
    }
  }

  stream.end();
}

